#include "emit.h"

void vmgen_emit_header(vmgen_buf_t *buf, const char *filename,
                       const vmgen_spec_t *spec) {
    vmgen_buf_appendf(buf,
        "/*\n"
        " * %s\n"
        " * Generated by vmgen for VM '%s' v%s\n"
        " * DO NOT EDIT — regenerate from spec instead.\n"
        " */\n\n",
        filename, spec->name, spec->version);
}

void vmgen_emit_guard_open(vmgen_buf_t *buf, const char *guard_name) {
    vmgen_buf_appendf(buf, "#ifndef %s\n#define %s\n\n", guard_name, guard_name);
}

void vmgen_emit_guard_close(vmgen_buf_t *buf, const char *guard_name) {
    vmgen_buf_appendf(buf, "\n#endif /* %s */\n", guard_name);
}
